{"cards": [{"node_code": "N_7cdaa494e5ff0df2", "definition": "港口机械及电气设备在运营维护层面的管理，涵盖设备台账、检修计划、使用规范、安全操作规程及维护保养制度。", "boundary": "本节点聚焦于“管理”与“维护”流程，而非设备本身的工程设计或制造。边界在于区分“设备管理”与“设备工程”（机械结构、电气原理设计归入相关工程节点）、“装卸工艺”（侧重作业流程而非设备状态）。若涉及设备采购、报废的经济分析，需视侧重归入经济管理或本节点。", "includes": ["港口起重机、输送机等机械设备的维护保养制度与检修计划", "港口电气系统（供电、照明、控制）的运行管理与安全规程", "设备使用规范、操作人员培训及设备状态监测管理"], "excludes": ["港口机械与电气设备的结构设计、制造工艺及新型研发", "港口整体调度指挥流程（归入港口调度管理）", "设备采购成本核算与投资回报分析（归入水路运输经济）"], "sibling_distinctions": [{"other_code": "N_d97c2c5133194ae3", "rule": "本节点侧重“物”（设备）的状态管理与维护；兄弟节点侧重“事”（作业）的调度指挥与流程优化。"}, {"other_code": "N_e4112faaaab526a8", "rule": "本节点侧重设备本身的“可用性”与“安全性”管理；兄弟节点侧重作业结果的“效率”与“质量”指标评估。"}], "cross_boundary_rule": "若内容涉及智能设备远程监控系统的管理流程，主挂载本节点；若涉及监控系统的具体算法或硬件设计，需视树中是否有对应智能技术节点，否则保留在本节点或待确认。"}, {"node_code": "N_4b76a429d2dbe5e7", "definition": "港口行政监管与口岸联检工作，涵盖港口监督、卫生检疫、海关监管及边防检查的管理制度、流程与协作机制。", "boundary": "本节点聚焦于港口作为口岸的“监管”与“执法”职能，而非港口内部的生产调度。边界在于区分“监管管理”与“业务操作”（如报关单证的具体填写归入业务操作，监管政策与流程归本节点）。若涉及国际贸易法律宏观研究，需视侧重归入经济或本节点。", "includes": ["港口行政监督、安全检查及卫生检疫的管理制度与执行流程", "海关监管、查验、征税及保税港区管理的业务规范", "边防检查、出入境管理及口岸联检协作机制"], "excludes": ["港口内部生产调度、装卸作业组织（归入港口调度或装卸指标）", "国际贸易宏观政策、关税理论及航运经济分析", "船舶在港期间的航行安全指挥（归入水运工作组织）"], "sibling_distinctions": [{"other_code": "N_dab39aed168673f9", "rule": "本节点侧重具体的“监管职能”（海关、检疫、边防）；兄弟节点侧重“机构架构”与整体行政管理体系。"}, {"other_code": "N_ccb05b0a566b6760", "rule": "本节点侧重监管工作的“执行流程”与“业务规范”；兄弟节点侧重“法规文本”与“制度条文”本身。"}], "cross_boundary_rule": "若内容涉及口岸智能化监管系统（如人脸识别、自动查验）的管理应用，主挂载本节点；若涉及系统技术实现，需视树中是否有对应智能技术节点。"}, {"node_code": "N_e4112faaaab526a8", "definition": "港口装卸作业的效率、质量与能力评估体系，涵盖吞吐量、作业时间、设备利用率、货损率等关键绩效指标（KPI）的统计与分析。", "boundary": "本节点聚焦于“指标”与“评估”，即对作业结果的量化衡量。边界在于区分“指标体系”与“作业组织”（如何安排作业归入调度或组织）、“设备管理”（设备维护归入设备管理）。若涉及基于指标的成本核算，需视侧重归入经济管理。", "includes": ["港口吞吐量、泊位利用率、船时利用率等核心效率指标的定义与统计", "装卸作业时间定额、劳动生产率及货损货差率的质量指标", "港口作业能力评估模型及绩效分析方法"], "excludes": ["具体的装卸工艺流程设计与优化（归入装卸技术与设备）", "港口调度指令的发布与执行过程（归入港口调度管理）", "基于指标数据的财务成本分析与利润核算（归入水路运输经济）"], "sibling_distinctions": [{"other_code": "N_d97c2c5133194ae3", "rule": "本节点侧重“结果”的量化评估（指标）；兄弟节点侧重“过程”的指挥与控制（调度）。"}, {"other_code": "N_7cdaa494e5ff0df2", "rule": "本节点侧重作业“效率”指标；兄弟节点侧重设备“状态”与“维护”管理。"}], "cross_boundary_rule": "若内容涉及利用大数据进行指标预测与智能优化，主挂载本节点（侧重指标应用）；若涉及大数据平台架构，需视树中是否有对应智能技术节点。"}]}
